const config = {
  "previewFeatures": [],
  "clientVersion": "7.9.1",
  "engineVersion": "e922089b7d7502aff4249d5da3420f6fa55fc6ad",
  "activeProvider": "postgresql",
  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ---------------------------------------------------------------------------\n// The spine. Kept deliberately thin here so M1 (the deal wizard) extends these\n// rather than migrating away from them.\n// ---------------------------------------------------------------------------\n\nenum StakeholderKind {\n  INDIVIDUAL\n  ENTITY\n}\n\nmodel Stakeholder {\n  id         String          @id @default(cuid())\n  kind       StakeholderKind @default(INDIVIDUAL)\n  name       String\n  idNumber   String?\n  /// Stored lowercase. Unique because sign-in links a login to the one row holding its\n  /// verified address, so a second row for the same person is a deal they never see.\n  email      String?         @unique\n  phone      String?\n  /// Supabase auth user id, set when someone signs in and claims this stakeholder.\n  /// Most stakeholders (landlords, tenants) never sign in and leave this null; it is\n  /// what separates \"a person on a deal\" from \"a person with a login\".\n  authUserId String?         @unique\n\n  /// Billing workspace membership. Property access is granted separately per tenancy.\n  teamId    String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  team              Team?              @relation(fields: [teamId], references: [id], onDelete: SetNull)\n  agencyMemberships AgencyMembership[]\n\n  tenanciesAsLandlord         Tenancy[]                   @relation(\"LandlordTenancies\")\n  tenanciesAsTenant           Tenancy[]                   @relation(\"TenantTenancies\")\n  tenanciesAsAgent            Tenancy[]                   @relation(\"AgentTenancies\")\n  tenancyCollaborations       TenancyCollaborator[]       @relation(\"TenancyCollaborator\")\n  tenancyAccessGranted        TenancyCollaborator[]       @relation(\"TenancyAccessGrantor\")\n  inspectionsRun              Inspection[]                @relation(\"InspectionConductor\")\n  reportInspections           Inspection[]                @relation(\"InspectionReportAgent\")\n  inspectionAccessGrants      InspectionAccessGrant[]\n  signatures                  Signature[]\n  deletionRequests            AccountDeletionRequest[]\n  maintenanceCasesReported    MaintenanceCase[]           @relation(\"MaintenanceReporter\")\n  maintenanceEvents           MaintenanceEvent[]\n  maintenanceVerifications    MaintenanceVerification[]\n  maintenanceEvidenceUploaded MaintenanceEvidence[]\n  responsibilityProposed      ResponsibilityProposal[]    @relation(\"ResponsibilityProposer\")\n  responsibilityResponded     ResponsibilityProposal[]    @relation(\"ResponsibilityResponder\")\n  notifications               Notification[]\n  deviceInstallations         DeviceInstallation[]\n  branding                    AgentBranding?\n  errorEvents                 ErrorEvent[]\n  productEvents               ProductEvent[]\n  acquisition                 AccountAcquisition?\n  reportEmails                ReportEmail[]\n  addendaCreated              ReportAddendum[]            @relation(\"AddendumCreator\")\n  addendaPublished            ReportAddendum[]            @relation(\"AddendumPublisher\")\n  addendaDisputed             ReportAddendum[]            @relation(\"AddendumDisputer\")\n  addendumAcknowledgements    AddendumAcknowledgement[]\n  findingPhotoDrafts          FindingPhotoDraft[]\n  assessmentResponses         AssessmentResponse[]\n  supportingDocumentRequests  SupportingDocumentRequest[]\n  supportingDocumentFiles     SupportingDocumentFile[]\n  /// The plan of an agent who is on no team. An agent on a team uses the team's.\n  subscription                Subscription?               @relation(\"OwnSubscription\")\n  subscriptionsManaged        Subscription[]              @relation(\"ManagedSubscriptions\")\n  googlePlayBillingAccounts   GooglePlayBillingAccount[]\n  appleBillingAccounts        AppleBillingAccount[]\n\n  @@index([name])\n  @@index([teamId])\n}\n\n/// One verified account's first observed acquisition and conversion milestones.\n/// Created only when a verified Auth user first claims/creates its stakeholder;\n/// existing linked accounts are never assigned a guessed signup date or source.\nmodel AccountAcquisition {\n  stakeholderId          String      @id\n  verifiedAt             DateTime\n  recordedAt             DateTime    @default(now())\n  /// Finite, validated client observations; absent attribution is \"unattributed\".\n  source                 String\n  medium                 String?\n  campaign               String?\n  landing                String?\n  entryPoint             String\n  excluded               Boolean     @default(false)\n  /// Stamped by the countersignature transaction, never client analytics.\n  firstCompletedReportAt DateTime?\n  /// A successful positive live Stripe invoice; not a trial, comp or entitlement.\n  firstPaidAt            DateTime?\n  firstPaidInvoiceId     String?     @unique\n  firstPaidAmount        Int?\n  firstPaidCurrency      String?\n  stakeholder            Stakeholder @relation(fields: [stakeholderId], references: [id], onDelete: Cascade)\n\n  @@index([verifiedAt])\n}\n\n/// A billing workspace set up with `pnpm team:set`. Membership does not grant or revoke\n/// property access; the lead agent shares each tenancy explicitly.\nmodel Team {\n  id        String   @id @default(cuid())\n  name      String   @unique\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  members      Stakeholder[]\n  subscription Subscription?\n}\n\nenum AgencyRole {\n  OWNER\n  MANAGER\n  AGENT\n}\n\nenum AgencyMembershipStatus {\n  INVITED\n  ACTIVE\n  REMOVED\n}\n\n/// Operational membership is separate from the existing billing-only Team.\nmodel Agency {\n  id                String             @id @default(cuid())\n  name              String\n  createdAt         DateTime           @default(now())\n  updatedAt         DateTime           @updatedAt\n  members           AgencyMembership[]\n  tenancies         Tenancy[]\n  activity          AgencyActivity[]\n  branding          AgencyBranding?\n  subscription      Subscription?\n  reportInspections Inspection[]       @relation(\"InspectionReportAgency\")\n}\n\n/// The shared identity on reports prepared in this operational team's workspace.\n/// The responsible agent's own CEA registration and phone remain on AgentBranding.\nmodel AgencyBranding {\n  agencyId      String   @id\n  agencyLicence String?\n  phone         String?\n  /// Private bucket path, at `agency-branding/<agencyId>/logo`.\n  logoPath      String?\n  updatedAt     DateTime @updatedAt\n\n  agency Agency @relation(fields: [agencyId], references: [id], onDelete: Cascade)\n}\n\nmodel AgencyMembership {\n  id            String                 @id @default(cuid())\n  agencyId      String\n  stakeholderId String\n  role          AgencyRole             @default(AGENT)\n  status        AgencyMembershipStatus @default(INVITED)\n  invitedById   String?\n  expiresAt     DateTime?\n  acceptedAt    DateTime?\n  removedAt     DateTime?\n  createdAt     DateTime               @default(now())\n  updatedAt     DateTime               @updatedAt\n  agency        Agency                 @relation(fields: [agencyId], references: [id], onDelete: Cascade)\n  stakeholder   Stakeholder            @relation(fields: [stakeholderId], references: [id], onDelete: Cascade)\n  notifications Notification[]\n\n  @@unique([agencyId, stakeholderId])\n  @@index([stakeholderId, status])\n}\n\n/// Append-only history; names are retained when an account is removed.\nmodel AgencyActivity {\n  id          String   @id @default(cuid())\n  agencyId    String\n  actorId     String\n  actorName   String\n  subjectId   String?\n  subjectName String?\n  action      String\n  createdAt   DateTime @default(now())\n  agency      Agency   @relation(fields: [agencyId], references: [id], onDelete: Cascade)\n\n  @@index([agencyId, createdAt])\n}\n\nenum Plan {\n  PRO\n}\n\n/// A workspace's paid or comped plan. A workspace is a team, or an agent on no team, so\n/// exactly one of teamId and stakeholderId is set (a CHECK constraint holds it). Free is\n/// the absence of a row. What a plan allows is decided in `src/lib/plan.ts` and nowhere\n/// else; this row only records what was bought.\nmodel Subscription {\n  id                   String    @id @default(cuid())\n  agencyId             String?   @unique\n  teamId               String?   @unique\n  stakeholderId        String?   @unique\n  plan                 Plan\n  seats                Int\n  /// Stripe's subscription status verbatim (active, trialing, past_due, canceled, ...),\n  /// Google Play SUBSCRIPTION_STATE_* verbatim, or \"comped\" for an operator plan.\n  status               String\n  stripeCustomerId     String?   @unique\n  stripeSubscriptionId String?   @unique\n  googlePlayPurchaseId String?   @unique\n  applePurchaseId      String?   @unique\n  currentPeriodEnd     DateTime?\n  cancelAtPeriodEnd    Boolean   @default(false)\n  /// The member who manages billing. Null once they delete their account, and then any\n  /// member of the workspace may.\n  managedById          String?\n  createdAt            DateTime  @default(now())\n  updatedAt            DateTime  @updatedAt\n\n  team               Team?               @relation(fields: [teamId], references: [id], onDelete: Cascade)\n  agency             Agency?             @relation(fields: [agencyId], references: [id], onDelete: Cascade)\n  stakeholder        Stakeholder?        @relation(\"OwnSubscription\", fields: [stakeholderId], references: [id], onDelete: Cascade)\n  managedBy          Stakeholder?        @relation(\"ManagedSubscriptions\", fields: [managedById], references: [id], onDelete: SetNull)\n  googlePlayPurchase GooglePlayPurchase? @relation(fields: [googlePlayPurchaseId], references: [id], onDelete: Restrict)\n  applePurchase      ApplePurchase?      @relation(fields: [applePurchaseId], references: [id], onDelete: Restrict)\n}\n\n/// Opaque StoreKit appAccountToken, created only for a verified payer/workspace.\n/// Erasure keeps the binding as a non-transferable purchase tombstone.\nmodel AppleBillingAccount {\n  id                  String          @id @default(uuid())\n  workspaceKey        String\n  stakeholderId       String?\n  retirementStartedAt DateTime?\n  createdAt           DateTime        @default(now())\n  stakeholder         Stakeholder?    @relation(fields: [stakeholderId], references: [id], onDelete: SetNull)\n  purchases           ApplePurchase[]\n\n  @@unique([workspaceKey, stakeholderId])\n  @@index([stakeholderId])\n}\n\n/// One renewal chain, always re-read from Apple's signed subscription status API.\nmodel ApplePurchase {\n  id                    String    @id @default(cuid())\n  originalTransactionId String    @unique\n  transactionId         String\n  accountId             String\n  productId             String\n  environment           String\n  state                 String\n  expiresAt             DateTime\n  autoRenewing          Boolean\n  grantedAt             DateTime?\n  rejectedAt            DateTime?\n  createdAt             DateTime  @default(now())\n  updatedAt             DateTime  @updatedAt\n\n  account      AppleBillingAccount @relation(fields: [accountId], references: [id], onDelete: Restrict)\n  subscription Subscription?\n\n  @@index([accountId])\n}\n\n/// Server-verified Google Play purchase history. Tokens never leave the server after\n/// submission and are never logged. Owner erasure retains a non-transferable tombstone.\nmodel GooglePlayBillingAccount {\n  /// Hash of a server-selected billing workspace and its payer, sent to Google Play.\n  id                  String               @id\n  workspaceKey        String\n  stakeholderId       String?\n  retirementStartedAt DateTime?\n  createdAt           DateTime             @default(now())\n  stakeholder         Stakeholder?         @relation(fields: [stakeholderId], references: [id], onDelete: SetNull)\n  purchases           GooglePlayPurchase[]\n\n  @@index([stakeholderId])\n  @@index([workspaceKey])\n}\n\nmodel GooglePlayPurchase {\n  id            String    @id @default(cuid())\n  purchaseToken String    @unique\n  accountId     String\n  productId     String\n  basePlanId    String\n  state         String\n  expiresAt     DateTime?\n  autoRenewing  Boolean\n  acknowledged  Boolean\n  testPurchase  Boolean\n  replacedById  String?\n  grantedAt     DateTime?\n  rejectedAt    DateTime?\n  refundReason  String?\n  refundedAt    DateTime?\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  account      GooglePlayBillingAccount @relation(fields: [accountId], references: [id], onDelete: Restrict)\n  subscription Subscription?\n\n  @@index([accountId])\n}\n\n/// The complete report identity for an agent's personal work. For team work, the\n/// responsible agent's CEA registration and contact are combined with AgencyBranding.\n/// With none set, a personal report reads as Kivilo's. Branding is presentation rather\n/// than signed report content, so the pinned agent and team use their current details.\nmodel AgentBranding {\n  stakeholderId   String   @id\n  agencyName      String\n  agencyLicence   String?\n  ceaRegistration String?\n  phone           String?\n  /// Private bucket path, at `branding/<stakeholderId>/logo`.\n  logoPath        String?\n  updatedAt       DateTime @updatedAt\n\n  stakeholder Stakeholder @relation(fields: [stakeholderId], references: [id], onDelete: Cascade)\n}\n\nenum PropertyType {\n  HDB\n  PRIVATE_NON_LANDED\n  LANDED\n  COMMERCIAL\n}\n\n/// The durable hub. Outlives every relationship on it.\nmodel Property {\n  id             String       @id @default(cuid())\n  line1          String\n  unit           String?\n  postalCode     String\n  type           PropertyType\n  createdAt      DateTime     @default(now())\n  updatedAt      DateTime     @updatedAt\n  archivedAt     DateTime?\n  trashedAt      DateTime?\n  trashExpiresAt DateTime?\n  trashedById    String?\n\n  tenancies Tenancy[]\n  assets    PropertyAsset[]\n  events    PropertyEvent[]\n  bin       BinItem[]\n\n  @@index([postalCode])\n}\n\n/// One append-only line of a property's history: who changed or deleted what, and when.\n/// Written in the same transaction as the change (`src/lib/property-history.ts`), never\n/// edited afterwards except to fold a burst of the same person's edits into one line.\nmodel PropertyEvent {\n  id           String   @id @default(cuid())\n  propertyId   String\n  tenancyId    String?\n  inspectionId String?\n  actorId      String?\n  actorName    String\n  kind         String\n  summary      String\n  /// Field changes as `{ changes: [{ field, from, to }] }`, or a count for a burst.\n  detail       Json?\n  /// The thing a burst folds into, e.g. `item:<id>`. Null for events that never fold.\n  subjectKey   String?\n  binItemId    String?\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  property Property @relation(fields: [propertyId], references: [id], onDelete: Cascade)\n  binItem  BinItem? @relation(fields: [binItemId], references: [id], onDelete: SetNull)\n\n  @@index([propertyId, createdAt])\n  @@index([subjectKey, actorId, updatedAt])\n}\n\n/// Something deleted from a working report, kept for 30 days so it can be restored.\n/// `rows` is the removed rows exactly as they were (`src/lib/bin.ts`); nothing reads\n/// them except Restore, so no report, fingerprint or PDF query needs to know the bin exists.\nmodel BinItem {\n  id           String    @id @default(cuid())\n  propertyId   String\n  tenancyId    String\n  inspectionId String\n  kind         String\n  label        String\n  rows         Json\n  deletedById  String?\n  deletedAt    DateTime  @default(now())\n  expiresAt    DateTime\n  restoredAt   DateTime?\n  restoredById String?\n\n  property Property        @relation(fields: [propertyId], references: [id], onDelete: Cascade)\n  events   PropertyEvent[]\n\n  @@index([expiresAt])\n  @@index([inspectionId])\n}\n\nmodel Tenancy {\n  id                  String           @id @default(cuid())\n  propertyId          String\n  landlordId          String\n  tenantId            String\n  agentId             String?\n  agencyId            String?\n  startDate           DateTime\n  endDate             DateTime\n  monthlyRent         Decimal          @db.Decimal(10, 2)\n  deposit             Decimal          @db.Decimal(10, 2)\n  /// Tenant pays up to this per repair, landlord the rest. Only prefills a cost\n  /// proposal; the tenant still accepts or rejects every one.\n  minorRepairCap      Decimal?         @db.Decimal(10, 2)\n  /// Human-confirmed clause and source agreement. The cap remains a proposal default.\n  minorRepairClause   Json?\n  /// Whether the agent may accept or reject a tenant's cost proposal for the landlord.\n  /// Only the landlord can change it.\n  agentMayAgreeCosts  Boolean          @default(true)\n  /// First N Singapore calendar days from the tenancy start, inclusive. Zero disables\n  /// move-in notices. Fixed once the tenant signs the check-in.\n  defectWindowDays    Int              @default(30)\n  /// Reminder choices belong to the tenancy, so collaborators see the same decision.\n  renewalDecision     RenewalDecision?\n  renewalSnoozedUntil DateTime?\n  /// A renewal is a new term on the same property, never an edit to the signed term.\n  renewedFromId       String?          @unique\n  createdAt           DateTime         @default(now())\n  updatedAt           DateTime         @updatedAt\n\n  property Property     @relation(fields: [propertyId], references: [id], onDelete: Cascade)\n  landlord Stakeholder  @relation(\"LandlordTenancies\", fields: [landlordId], references: [id])\n  tenant   Stakeholder  @relation(\"TenantTenancies\", fields: [tenantId], references: [id])\n  agent    Stakeholder? @relation(\"AgentTenancies\", fields: [agentId], references: [id])\n  agency   Agency?      @relation(fields: [agencyId], references: [id])\n\n  inspections                Inspection[]\n  collaborators              TenancyCollaborator[]\n  notifications              Notification[]\n  maintenanceCases           MaintenanceCase[]\n  supportingDocumentRequests SupportingDocumentRequest[]\n  renewedFrom                Tenancy?                    @relation(\"TenancyRenewal\", fields: [renewedFromId], references: [id], onDelete: SetNull)\n  renewedAs                  Tenancy?                    @relation(\"TenancyRenewal\")\n\n  @@index([propertyId])\n  @@index([agencyId])\n}\n\n/// Full working access to one tenancy. Inspection conductors remain attribution only;\n/// removing this grant revokes access even when the person conducted an inspection.\nmodel TenancyCollaborator {\n  id            String   @id @default(cuid())\n  tenancyId     String\n  stakeholderId String\n  /// Null for historical access preserved by the migration, or a deleted grantor.\n  grantedById   String?\n  createdAt     DateTime @default(now())\n\n  tenancy     Tenancy      @relation(fields: [tenancyId], references: [id], onDelete: Cascade)\n  stakeholder Stakeholder  @relation(\"TenancyCollaborator\", fields: [stakeholderId], references: [id], onDelete: Cascade)\n  grantedBy   Stakeholder? @relation(\"TenancyAccessGrantor\", fields: [grantedById], references: [id], onDelete: SetNull)\n\n  @@unique([tenancyId, stakeholderId])\n  @@index([stakeholderId])\n}\n\nenum RenewalDecision {\n  NOT_RENEWING\n  DISMISSED\n}\n\n// ---------------------------------------------------------------------------\n// M4: check-in / check-out\n// ---------------------------------------------------------------------------\n\nenum InspectionKind {\n  CHECK_IN\n  CHECK_OUT\n}\n\nenum InspectionStatus {\n  DRAFT\n  CAPTURING\n  PROCESSING\n  REVIEW\n  AWAITING_SIGNATURE\n  COMPLETED\n  FAILED\n}\n\nenum FurnishingLevel {\n  FULLY_FURNISHED\n  PARTIALLY_FURNISHED\n  UNFURNISHED\n}\n\nmodel Inspection {\n  id                String           @id @default(cuid())\n  /// The phone's id for a new check-in, so a retried create returns the same one.\n  clientId          String?          @unique\n  tenancyId         String\n  kind              InspectionKind\n  status            InspectionStatus @default(DRAFT)\n  /// Compatibility copy for app builds released before furnishing became three-way.\n  fullyFurnished    Boolean          @default(true)\n  /// Determines which editable starter rows a newly added room receives.\n  furnishingLevel   FurnishingLevel  @default(FULLY_FURNISHED)\n  conductedById     String?\n  /// Responsible agent frozen at Send. Handover changes Tenancy.agentId only.\n  reportAgentId     String?\n  /// Operational team frozen at Send. Later assignment cannot rewrite the report header.\n  reportAgencyId    String?\n  reportAgentFrozen Boolean          @default(false)\n  conductedAt       DateTime?\n  /// A check-out points at the check-in it is measured against.\n  baselineId        String?          @unique\n  summary           String?\n  processingError   String?\n  /// Unguessable bearer token for the read-only report link handed to the landlord\n  /// and tenant. Null until someone shares the report. Revoked by setting it back to\n  /// null, which is why it is nullable rather than generated with the row.\n  shareToken        String?          @unique\n  sharedAt          DateTime?\n  /// Consent by the inspector before home media is sent to external AI providers.\n  aiConsentAt       DateTime?\n  aiConsentById     String?\n  createdAt         DateTime         @default(now())\n  updatedAt         DateTime         @updatedAt\n\n  tenancy      Tenancy      @relation(fields: [tenancyId], references: [id], onDelete: Cascade)\n  conductedBy  Stakeholder? @relation(\"InspectionConductor\", fields: [conductedById], references: [id])\n  reportAgent  Stakeholder? @relation(\"InspectionReportAgent\", fields: [reportAgentId], references: [id])\n  reportAgency Agency?      @relation(\"InspectionReportAgency\", fields: [reportAgencyId], references: [id])\n  baseline     Inspection?  @relation(\"Baseline\", fields: [baselineId], references: [id])\n  checkOut     Inspection?  @relation(\"Baseline\")\n\n  rooms              Room[]\n  findings           Finding[]\n  findingPhotoDrafts FindingPhotoDraft[]\n  signatures         Signature[]\n  assessments        AssessmentVersion[]\n  issuedReportFiles  IssuedReportFile[]\n  reportEmails       ReportEmail[]\n  addenda            ReportAddendum[]\n  accessGrants       InspectionAccessGrant[]\n  moveInDefectCases  MaintenanceCase[]       @relation(\"MoveInDefectInspection\")\n\n  @@index([tenancyId, kind])\n  @@index([reportAgencyId])\n}\n\n/// Exact inspection access preserved from the old conductor rule. This never grants\n/// access to sibling inspections or the tenancy's repairs, and is explicitly revocable.\nmodel InspectionAccessGrant {\n  id            String   @id @default(cuid())\n  inspectionId  String\n  stakeholderId String\n  createdAt     DateTime @default(now())\n\n  inspection  Inspection  @relation(fields: [inspectionId], references: [id], onDelete: Cascade)\n  stakeholder Stakeholder @relation(fields: [stakeholderId], references: [id], onDelete: Cascade)\n\n  @@unique([inspectionId, stakeholderId])\n  @@index([stakeholderId])\n}\n\nenum CaptureKind {\n  /// Narrated walkthrough of one room.\n  VIDEO\n  /// Deliberate still: a label, a serial plate, a meter face, a specific defect.\n  /// Video is downsampled too far to read small print; this is what OCR runs on.\n  PHOTO\n}\n\n/// The evidence. AI is the scribe; this is the witness.\n/// Captures belong to a room, not to the inspection, so an inspector can re-shoot\n/// one room without disturbing rooms already reviewed.\nmodel Capture {\n  id             String      @id @default(cuid())\n  /// Stable native-client id. A lost registration response must not create another row.\n  clientId       String?     @unique\n  roomId         String\n  kind           CaptureKind @default(VIDEO)\n  storagePath    String      @unique\n  mimeType       String\n  sizeBytes      Int\n  durationSec    Int?\n  /// What the inspector said while recording, or typed against a photo.\n  transcript     String?\n  /// Inspector's own note attached at capture time, before any model sees it.\n  note           String?\n  /// Rings and arrows the inspector drew over this photo, with the intrinsic size of\n  /// the upright image they were drawn against. Data over an unmodified original: the\n  /// object at storagePath is never rewritten. Shape and parser live in\n  /// src/lib/annotations.ts. Human-authored by construction, so it carries its own\n  /// author and time and never a confidence.\n  annotations    Json?\n  processedAt    DateTime?\n  /// A small still stored next to the capture, so a list can show it without loading the\n  /// original: a video's representative frame, or a photo resized to 640px WebP. Made by the\n  /// poster cron (src/lib/poster.ts); null until then.\n  posterPath     String?     @unique\n  /// Failed poster runs. The cron stops after a few, so one unreadable file cannot\n  /// occupy every run.\n  posterAttempts Int         @default(0)\n  createdAt      DateTime    @default(now())\n\n  room         Room             @relation(fields: [roomId], references: [id], onDelete: Cascade)\n  items        InspectionItem[]\n  itemEvidence ItemEvidence[]\n\n  @@index([roomId])\n}\n\n/// The small copy of a stored photo that is not a Capture: a finding photo, repair\n/// evidence or an update's photo. Keyed by the original's path, so an update photo that\n/// reuses repair evidence shares its poster. The poster is stored beside the original as\n/// `<path>.poster.webp`, so a prefix purge takes it too, and the object purge removes it\n/// with its original (src/lib/storage-purge.ts). Made by the poster cron.\nmodel PhotoPoster {\n  sourcePath String   @id\n  /// Null until made, and while a failing photo is retried.\n  posterPath String?  @unique\n  attempts   Int      @default(0)\n  createdAt  DateTime @default(now())\n}\n\nenum RoomStatus {\n  /// Created by the inspector, nothing captured yet.\n  PENDING\n  CAPTURING\n  PROCESSING\n  /// Draft items exist, awaiting a human pass.\n  REVIEW\n  REVIEWED\n  FAILED\n}\n\nmodel Room {\n  id                  String     @id @default(cuid())\n  inspectionId        String\n  name                String\n  order               Int\n  status              RoomStatus @default(PENDING)\n  processingError     String?\n  processingAttemptId String?\n  processingStartedAt DateTime?\n  /// On a check-out room, the room as the check-out began from it, frozen when it\n  /// started (`RoomBaseline` in `src/lib/check-in-reference.ts`): its lines and the photos\n  /// agreed of it, the check-in's and any acknowledged addendum's. Null on check-ins, on\n  /// rooms added during a check-out, and on check-outs started before it existed.\n  baseline            Json?\n  createdAt           DateTime   @default(now())\n  updatedAt           DateTime   @updatedAt\n\n  inspection Inspection       @relation(fields: [inspectionId], references: [id], onDelete: Cascade)\n  captures   Capture[]\n  items      InspectionItem[]\n\n  @@index([inspectionId])\n}\n\nenum ItemCategory {\n  FIXTURE\n  APPLIANCE\n  FURNITURE\n  SURFACE\n  METER\n}\n\nenum ItemCondition {\n  NEW\n  GOOD\n  FAIR\n  POOR\n  DAMAGED\n}\n\nmodel InspectionItem {\n  id                 String        @id @default(cuid())\n  roomId             String\n  name               String\n  category           ItemCategory\n  condition          ItemCondition\n  quantity           Int           @default(1)\n  notes              String?\n  /// Make, model, and serial read verbatim off a photographed label or plate.\n  /// This is what makes an inventory line identify one specific object rather than\n  /// a category of object. That difference is what decides a deposit dispute.\n  identifier         String?\n  /// Meter reading, verbatim as spoken or read. Free text, because units vary.\n  meterReading       String?\n  /// The capture this item was read from, so the report can show its evidence.\n  sourceCaptureId    String?\n  /// Where in that capture the item is clearest. Video captures only.\n  sourceTimestampSec Int?\n  /// Model self-reported confidence, 0–1. Null once a human has taken ownership.\n  confidence         Float?\n  editedByHuman      Boolean       @default(false)\n  /// A durable property asset selected by a human. Identifier similarity may be\n  /// suggested in UI, but model output never links assets automatically.\n  propertyAssetId    String?\n  /// On a check-out row, the key of the check-in line it was copied from (`item:<id>` or\n  /// `entry:<id>`, as `currentState` names lines), so the inspector can see what it was\n  /// at check-in after editing it. Null on check-ins and on rows added during check-out.\n  baselineKey        String?\n  createdAt          DateTime      @default(now())\n  updatedAt          DateTime      @updatedAt\n\n  room          Room           @relation(fields: [roomId], references: [id], onDelete: Cascade)\n  sourceCapture Capture?       @relation(fields: [sourceCaptureId], references: [id], onDelete: SetNull)\n  propertyAsset PropertyAsset? @relation(fields: [propertyAssetId], references: [id], onDelete: SetNull)\n  evidence      ItemEvidence[]\n\n  findingsAsSubject  Finding[] @relation(\"FindingItem\")\n  findingsAsBaseline Finding[] @relation(\"FindingBaselineItem\")\n\n  @@index([roomId])\n  @@index([propertyAssetId])\n}\n\n/// A human-curated link from an inventory line to one or more original room captures.\n/// Notes and photo marks remain on Capture, so the same evidence is never copied or\n/// rewritten when it is attached to several items.\nmodel ItemEvidence {\n  itemId    String\n  captureId String\n  createdAt DateTime @default(now())\n\n  item    InspectionItem @relation(fields: [itemId], references: [id], onDelete: Cascade)\n  capture Capture        @relation(fields: [captureId], references: [id], onDelete: Cascade)\n\n  @@id([itemId, captureId])\n  @@index([captureId])\n}\n\n// ---------------------------------------------------------------------------\n// M5: longitudinal property maintenance\n// ---------------------------------------------------------------------------\n\nenum PropertyAssetCategory {\n  APPLIANCE\n  FIXTURE\n  FURNITURE\n  SURFACE\n  SYSTEM\n  OTHER\n}\n\nmodel PropertyAsset {\n  id         String                @id @default(cuid())\n  propertyId String\n  name       String\n  category   PropertyAssetCategory\n  roomLabel  String?\n  identifier String?\n  active     Boolean               @default(true)\n  createdAt  DateTime              @default(now())\n  updatedAt  DateTime              @updatedAt\n\n  property         Property              @relation(fields: [propertyId], references: [id], onDelete: Cascade)\n  inspectionItems  InspectionItem[]\n  maintenanceCases MaintenanceCase[]\n  addendumEntries  ReportAddendumEntry[]\n\n  @@index([propertyId, active])\n  @@index([propertyId, identifier])\n}\n\nenum MaintenanceCategory {\n  APPLIANCE\n  PLUMBING\n  LOCKSMITH\n  ELECTRICAL\n  AIR_CONDITIONING\n  STRUCTURAL\n  PEST\n  OTHER\n}\n\nenum MaintenancePriority {\n  ROUTINE\n  URGENT\n  SAFETY_EMERGENCY\n}\n\nenum MaintenanceStatus {\n  REPORTED\n  ACKNOWLEDGED\n  SCHEDULED\n  AWAITING_CONFIRMATION\n  RESOLVED\n  CLOSED_NO_ACTION\n}\n\nmodel MaintenanceCase {\n  id                       String              @id @default(cuid())\n  clientId                 String?             @unique\n  tenancyId                String\n  propertyAssetId          String?\n  /// What the reporter typed when the item is not in the register, such as a toilet bowl.\n  itemName                 String?\n  reportedById             String\n  category                 MaintenanceCategory\n  priority                 MaintenancePriority @default(ROUTINE)\n  title                    String\n  description              String\n  status                   MaintenanceStatus   @default(REPORTED)\n  resolutionReason         String?\n  acknowledgedAt           DateTime?\n  resolvedAt               DateTime?\n  /// A timely tenant report reserves its move-in notice while evidence uploads finish.\n  wasPresentAtMoveIn       Boolean             @default(false)\n  /// Pin the signed check-in when the intent is recorded; later reports cannot retarget it.\n  moveInDefectInspectionId String?\n  createdAt                DateTime            @default(now())\n  updatedAt                DateTime            @updatedAt\n\n  tenancy                 Tenancy                  @relation(fields: [tenancyId], references: [id], onDelete: Cascade)\n  propertyAsset           PropertyAsset?           @relation(fields: [propertyAssetId], references: [id], onDelete: SetNull)\n  reportedBy              Stakeholder              @relation(\"MaintenanceReporter\", fields: [reportedById], references: [id])\n  events                  MaintenanceEvent[]\n  visits                  MaintenanceVisit[]\n  evidence                MaintenanceEvidence[]\n  findings                Finding[]\n  responsibilityProposals ResponsibilityProposal[]\n  addendumEntries         ReportAddendumEntry[]\n  moveInDefectInspection  Inspection?              @relation(\"MoveInDefectInspection\", fields: [moveInDefectInspectionId], references: [id], onDelete: SetNull)\n  moveInDefectAddendum    ReportAddendum?          @relation(\"MoveInDefectSource\")\n\n  @@index([tenancyId, status, createdAt])\n  @@index([propertyAssetId, createdAt])\n}\n\nenum MaintenanceEventKind {\n  REPORTED\n  COMMENT\n  STATUS_CHANGED\n  VISIT_RECORDED\n  VERIFICATION\n  REOPENED\n  RESPONSIBILITY_PROPOSED\n  RESPONSIBILITY_ACCEPTED\n  RESPONSIBILITY_REJECTED\n  RESPONSIBILITY_WITHDRAWN\n}\n\nmodel MaintenanceEvent {\n  id        String               @id @default(cuid())\n  caseId    String\n  actorId   String?\n  kind      MaintenanceEventKind\n  body      String?\n  metadata  Json?\n  createdAt DateTime             @default(now())\n\n  maintenanceCase MaintenanceCase @relation(fields: [caseId], references: [id], onDelete: Cascade)\n  actor           Stakeholder?    @relation(fields: [actorId], references: [id], onDelete: SetNull)\n\n  @@index([caseId, createdAt])\n}\n\nmodel MaintenanceVisit {\n  id          String    @id @default(cuid())\n  caseId      String\n  providerId  String?\n  scheduledAt DateTime?\n  completedAt DateTime?\n  notes       String?\n  cost        Decimal?  @db.Decimal(10, 2)\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  maintenanceCase MaintenanceCase          @relation(fields: [caseId], references: [id], onDelete: Cascade)\n  provider        ServiceProvider?         @relation(fields: [providerId], references: [id], onDelete: SetNull)\n  evidence        MaintenanceEvidence[]\n  verification    MaintenanceVerification?\n\n  @@index([caseId, completedAt])\n}\n\nenum MaintenanceEvidencePurpose {\n  BEFORE\n  AFTER\n  RECEIPT\n}\n\nmodel MaintenanceEvidence {\n  id           String                     @id @default(cuid())\n  clientId     String                     @unique\n  caseId       String\n  visitId      String?\n  uploadedById String\n  purpose      MaintenanceEvidencePurpose\n  storagePath  String                     @unique\n  mimeType     String\n  sizeBytes    Int\n  note         String?\n  /// Marks drawn by the uploader, in the shape of `Capture.annotations`.\n  annotations  Json?\n  createdAt    DateTime                   @default(now())\n\n  maintenanceCase MaintenanceCase   @relation(fields: [caseId], references: [id], onDelete: Cascade)\n  visit           MaintenanceVisit? @relation(fields: [visitId], references: [id], onDelete: SetNull)\n  uploadedBy      Stakeholder       @relation(fields: [uploadedById], references: [id])\n\n  @@index([caseId, createdAt])\n  @@index([visitId])\n}\n\nenum MaintenanceVerificationOutcome {\n  FIXED\n  NOT_FIXED\n}\n\nmodel MaintenanceVerification {\n  id           String                         @id @default(cuid())\n  visitId      String                         @unique\n  verifiedById String\n  outcome      MaintenanceVerificationOutcome\n  note         String?\n  createdAt    DateTime                       @default(now())\n\n  visit      MaintenanceVisit @relation(fields: [visitId], references: [id], onDelete: Cascade)\n  verifiedBy Stakeholder      @relation(fields: [verifiedById], references: [id])\n}\n\nenum RepairParty {\n  LANDLORD\n  TENANT\n}\n\nenum CostPayer {\n  LANDLORD\n  TENANT\n  SHARED\n}\n\nenum ResponsibilityBasis {\n  MINOR_REPAIR_CLAUSE\n  TENANT_CAUSED\n  FAIR_WEAR\n  LANDLORD_OBLIGATION\n  OTHER\n}\n\nenum ProposalStatus {\n  PENDING\n  ACCEPTED\n  REJECTED\n  WITHDRAWN\n  SUPERSEDED\n}\n\n/// Who arranges a repair and who pays for it, as one side proposes and the other\n/// answers. Append-only: changing an agreement is a new proposal, never an edit.\n/// At most one PENDING and one ACCEPTED per case, enforced by partial unique indexes\n/// in the migration because Prisma cannot express them.\nmodel ResponsibilityProposal {\n  id            String              @id @default(cuid())\n  caseId        String\n  proposedById  String\n  arrangedBy    RepairParty\n  payer         CostPayer\n  /// Required when payer is SHARED: the tenant pays up to this, the landlord the rest.\n  tenantCap     Decimal?            @db.Decimal(10, 2)\n  basis         ResponsibilityBasis\n  reason        String\n  /// Free text such as \"Clause 5(c)\" until tenancy agreements are extracted.\n  clauseRef     String?\n  status        ProposalStatus      @default(PENDING)\n  respondedById String?\n  respondedAt   DateTime?\n  responseNote  String?\n  createdAt     DateTime            @default(now())\n\n  maintenanceCase MaintenanceCase @relation(fields: [caseId], references: [id], onDelete: Cascade)\n  proposedBy      Stakeholder     @relation(\"ResponsibilityProposer\", fields: [proposedById], references: [id])\n  respondedBy     Stakeholder?    @relation(\"ResponsibilityResponder\", fields: [respondedById], references: [id])\n\n  @@index([caseId, createdAt])\n}\n\nenum ServiceProviderCategory {\n  PLUMBING\n  LOCKSMITH\n}\n\nmodel ServiceProvider {\n  id             String                  @id @default(cuid())\n  name           String\n  category       ServiceProviderCategory\n  phone          String\n  whatsapp       String?\n  serviceAreas   String[]\n  hours          String?\n  lastVerifiedAt DateTime\n  active         Boolean                 @default(true)\n  createdAt      DateTime                @default(now())\n  updatedAt      DateTime                @updatedAt\n\n  visits MaintenanceVisit[]\n\n  @@unique([category, phone])\n  @@index([category, active])\n}\n\nenum NotificationKind {\n  SUPPORTING_DOCUMENT_REQUESTED\n  SUPPORTING_DOCUMENT_UPLOADED\n  AGENCY_INVITATION\n  PROPERTY_SHARED\n  MAINTENANCE_REPORTED\n  MAINTENANCE_STATUS\n  MAINTENANCE_VISIT\n  MAINTENANCE_VERIFICATION\n  MAINTENANCE_RESPONSIBILITY\n  REPEAT_REPAIR\n  /// An addendum to a signed report was published and waits for this party.\n  REPORT_UPDATED\n  RENEWAL_DUE\n}\n\n/// Optional private tenancy paperwork, separate from the signed condition report.\nenum SupportingDocumentKind {\n  SUPPORTING\n  TENANCY_AGREEMENT\n}\n\nmodel SupportingDocumentRequest {\n  id            String                 @id @default(cuid())\n  tenancyId     String\n  clientId      String\n  title         String\n  kind          SupportingDocumentKind @default(SUPPORTING)\n  requestedById String\n  requestedAt   DateTime               @default(now())\n\n  tenancy     Tenancy                  @relation(fields: [tenancyId], references: [id], onDelete: Cascade)\n  requestedBy Stakeholder              @relation(fields: [requestedById], references: [id])\n  files       SupportingDocumentFile[]\n\n  @@unique([tenancyId, clientId])\n  @@index([requestedById])\n}\n\n/// Created before issuing an upload URL. Pending rows preserve immutable upload\n/// ownership and the cleanup path; only verified storage bytes set submittedAt.\nmodel SupportingDocumentFile {\n  id            String    @id @default(cuid())\n  requestId     String\n  clientId      String    @unique\n  storagePath   String    @unique\n  fileName      String\n  mimeType      String\n  byteSize      Int\n  submittedById String\n  createdAt     DateTime  @default(now())\n  submittedAt   DateTime?\n\n  request     SupportingDocumentRequest @relation(fields: [requestId], references: [id], onDelete: Cascade)\n  submittedBy Stakeholder               @relation(fields: [submittedById], references: [id])\n\n  @@index([requestId, submittedAt])\n  @@index([submittedById])\n}\n\nenum DevicePlatform {\n  ANDROID\n  IOS\n}\n\nmodel DeviceInstallation {\n  id            String         @id @default(cuid())\n  stakeholderId String\n  token         String         @unique\n  platform      DevicePlatform\n  lastSeenAt    DateTime       @default(now())\n  disabledAt    DateTime?\n  createdAt     DateTime       @default(now())\n  updatedAt     DateTime       @updatedAt\n\n  stakeholder Stakeholder                @relation(fields: [stakeholderId], references: [id], onDelete: Cascade)\n  deliveries  NotificationPushDelivery[]\n\n  @@index([stakeholderId, disabledAt, lastSeenAt])\n}\n\nmodel Notification {\n  id                 String           @id @default(cuid())\n  recipientId        String\n  tenancyId          String?\n  agencyMembershipId String?\n  kind               NotificationKind\n  title              String\n  body               String\n  href               String?\n  dedupeKey          String?          @unique\n  readAt             DateTime?\n  emailTo            String?\n  emailAttempts      Int              @default(0)\n  emailSentAt        DateTime?\n  emailError         String?\n  pushExpandedAt     DateTime?\n  createdAt          DateTime         @default(now())\n\n  recipient        Stakeholder                @relation(fields: [recipientId], references: [id], onDelete: Cascade)\n  tenancy          Tenancy?                   @relation(fields: [tenancyId], references: [id], onDelete: Cascade)\n  agencyMembership AgencyMembership?          @relation(fields: [agencyMembershipId], references: [id], onDelete: Cascade)\n  pushDeliveries   NotificationPushDelivery[]\n\n  @@index([recipientId, readAt, createdAt])\n  @@index([tenancyId, recipientId])\n  @@index([emailSentAt, emailAttempts, createdAt])\n  @@index([pushExpandedAt, createdAt])\n}\n\nmodel NotificationPushDelivery {\n  id             String    @id @default(cuid())\n  notificationId String\n  installationId String\n  attempts       Int       @default(0)\n  claimedAt      DateTime?\n  sentAt         DateTime?\n  error          String?\n  createdAt      DateTime  @default(now())\n  updatedAt      DateTime  @updatedAt\n\n  notification Notification       @relation(fields: [notificationId], references: [id], onDelete: Cascade)\n  installation DeviceInstallation @relation(fields: [installationId], references: [id], onDelete: Cascade)\n\n  @@unique([notificationId, installationId])\n  @@index([sentAt, attempts, createdAt])\n}\n\nenum ChangeType {\n  UNCHANGED\n  WEAR\n  DAMAGE\n  MISSING\n  IMPROVED\n}\n\nenum Verdict {\n  TENANT_LIABLE\n  FAIR_WEAR\n  DISPUTED\n  UNDECIDED\n}\n\n/// Check-out only. The dispute moment, drafted by the model and owned by a human.\nmodel Finding {\n  id                String     @id @default(cuid())\n  inspectionId      String\n  /// A client save id makes retrying a lost create response exactly once.\n  clientId          String?    @unique\n  itemId            String?\n  baselineItemId    String?\n  /// Human-selected maintenance history to preserve with a published assessment.\n  maintenanceCaseId String?\n  changeType        ChangeType\n  verdict           Verdict    @default(UNDECIDED)\n  rationale         String\n  estimatedCost     Decimal?   @db.Decimal(10, 2)\n  confidence        Float?\n  editedByHuman     Boolean    @default(false)\n  createdAt         DateTime   @default(now())\n  updatedAt         DateTime   @updatedAt\n\n  inspection      Inspection          @relation(fields: [inspectionId], references: [id], onDelete: Cascade)\n  item            InspectionItem?     @relation(\"FindingItem\", fields: [itemId], references: [id], onDelete: SetNull)\n  baselineItem    InspectionItem?     @relation(\"FindingBaselineItem\", fields: [baselineItemId], references: [id], onDelete: SetNull)\n  maintenanceCase MaintenanceCase?    @relation(fields: [maintenanceCaseId], references: [id], onDelete: SetNull)\n  photos          FindingPhoto[]\n  photoDrafts     FindingPhotoDraft[]\n\n  @@index([inspectionId])\n  @@index([maintenanceCaseId])\n}\n\n/// Personal working photos before Save. This is not a visible finding. A discarded\n/// draft remains a tombstone so delayed queue requests cannot recreate its uploads.\nmodel FindingPhotoDraft {\n  id           String    @id\n  inspectionId String\n  createdById  String\n  findingId    String?\n  savedAt      DateTime?\n  discardedAt  DateTime?\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n\n  inspection Inspection     @relation(fields: [inspectionId], references: [id], onDelete: Cascade)\n  createdBy  Stakeholder    @relation(fields: [createdById], references: [id])\n  finding    Finding?       @relation(fields: [findingId], references: [id], onDelete: SetNull)\n  photos     FindingPhoto[]\n\n  @@index([inspectionId, findingId, savedAt, discardedAt])\n  @@index([createdById])\n}\n\n/// Intent first, bytes second, registration last. Stored photographs never change;\n/// annotations stay beside them and are copied by value into each assessment version.\nmodel FindingPhoto {\n  clientId     String    @id\n  draftId      String\n  findingId    String?\n  storagePath  String    @unique\n  mimeType     String\n  sizeBytes    Int?\n  note         String?\n  annotations  Json?\n  registeredAt DateTime?\n  deletedAt    DateTime?\n  /// Once any assessment includes these bytes, deleting working rows never purges them.\n  publishedAt  DateTime?\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n\n  draft   FindingPhotoDraft @relation(fields: [draftId], references: [id], onDelete: Cascade)\n  finding Finding?          @relation(fields: [findingId], references: [id], onDelete: SetNull)\n\n  @@index([findingId, deletedAt, createdAt])\n  @@index([draftId, deletedAt])\n}\n\nmodel Signature {\n  id            String   @id @default(cuid())\n  inspectionId  String\n  stakeholderId String\n  signedAt      DateTime @default(now())\n  ipAddress     String?\n  /// data: URL of the drawn signature.\n  imageData     String\n  /// sha256 of the report content this person signed (`src/lib/report-fingerprint.ts`).\n  /// Null on signatures taken before it existed.\n  contentHash   String?\n\n  inspection  Inspection  @relation(fields: [inspectionId], references: [id], onDelete: Cascade)\n  stakeholder Stakeholder @relation(fields: [stakeholderId], references: [id])\n\n  @@unique([inspectionId, stakeholderId])\n}\n\nenum ReportEmailKind {\n  /// \"Please review and sign\", with a link to /sign/[inspectionId].\n  SIGNATURE_REQUEST\n  /// \"Both parties have signed\", with the signed PDF attached.\n  SIGNED_COPY\n  /// Tenant's handover instructions and move-in defect deadline, after their signature.\n  TENANT_HANDOVER\n}\n\n/// Outbox for report emails (`src/lib/report-email.ts`). A row is written in the same\n/// transaction as the change that calls for it (Send, or the second signature) and\n/// `/api/internal/report-emails` delivers it, so a Resend outage delays an email\n/// instead of failing a signature.\nmodel ReportEmail {\n  id           String          @id @default(cuid())\n  inspectionId String\n  recipientId  String\n  kind         ReportEmailKind\n  /// Makes the signed copy once only per recipient. Null for signature requests, which\n  /// the agent may resend.\n  dedupeKey    String?         @unique\n  /// The address it went to, read from the recipient at delivery.\n  emailTo      String?\n  attempts     Int             @default(0)\n  /// Not before this. Pushed back exponentially after each failure.\n  retryAt      DateTime        @default(now())\n  sentAt       DateTime?\n  error        String?\n  createdAt    DateTime        @default(now())\n\n  inspection Inspection  @relation(fields: [inspectionId], references: [id], onDelete: Cascade)\n  recipient  Stakeholder @relation(fields: [recipientId], references: [id], onDelete: Cascade)\n\n  @@index([sentAt, attempts, retryAt])\n  @@index([inspectionId, recipientId])\n}\n\n/// A human-published, immutable assessment. The signed inventory has its own lifecycle.\nmodel AssessmentVersion {\n  id            String   @id @default(cuid())\n  inspectionId  String\n  version       Int\n  snapshot      Json\n  contentHash   String\n  publishedAt   DateTime @default(now())\n  publishedById String\n\n  inspection Inspection           @relation(fields: [inspectionId], references: [id], onDelete: Cascade)\n  responses  AssessmentResponse[]\n\n  @@unique([inspectionId, version])\n  @@index([inspectionId, publishedAt])\n}\n\n/// A dated update to a COMPLETED check-in, after it was signed: an appliance replaced, a\n/// fixture removed. Never an edit to the signed rows; see plans/report-addenda.md.\n/// A draft has no number and is the agent's working copy, entries and photos included.\n/// Publishing numbers it, writes `snapshot` and `contentHash`, and freezes it. It counts\n/// (check-out baseline, timeline) only from `acknowledgedAt`, when both the landlord and\n/// the tenant have acknowledged it.\nmodel ReportAddendum {\n  id                      String    @id @default(cuid())\n  inspectionId            String\n  number                  Int?\n  title                   String\n  reason                  String?\n  /// The day the change happened, which is what the \"Updated\" banner shows.\n  effectiveDate           DateTime\n  createdById             String\n  createdAt               DateTime  @default(now())\n  updatedAt               DateTime  @updatedAt\n  publishedAt             DateTime?\n  publishedById           String?\n  /// Everything the report draws, by value. Shape in src/lib/addenda.ts.\n  snapshot                Json?\n  contentHash             String?\n  acknowledgedAt          DateTime?\n  /// A tenant's dated move-in notice, published directly from their maintenance report.\n  sourceMaintenanceCaseId String?   @unique\n  disputedAt              DateTime?\n  disputedById            String?\n  disputeReason           String?\n\n  inspection            Inspection                @relation(fields: [inspectionId], references: [id], onDelete: Cascade)\n  createdBy             Stakeholder               @relation(\"AddendumCreator\", fields: [createdById], references: [id])\n  publishedBy           Stakeholder?              @relation(\"AddendumPublisher\", fields: [publishedById], references: [id])\n  entries               ReportAddendumEntry[]\n  acknowledgements      AddendumAcknowledgement[]\n  sourceMaintenanceCase MaintenanceCase?          @relation(\"MoveInDefectSource\", fields: [sourceMaintenanceCaseId], references: [id], onDelete: SetNull)\n  disputedBy            Stakeholder?              @relation(\"AddendumDisputer\", fields: [disputedById], references: [id])\n\n  @@unique([inspectionId, number])\n  @@index([inspectionId, createdAt])\n}\n\nenum AddendumChange {\n  ADDED\n  REPLACED\n  REMOVED\n}\n\n/// One line of an addendum while it is drafted. Rendering reads the snapshot, never this.\nmodel ReportAddendumEntry {\n  id                String         @id @default(cuid())\n  addendumId        String\n  change            AddendumChange\n  roomName          String\n  /// The line a REPLACED or REMOVED entry changes: `item:<InspectionItem id>` for a signed\n  /// check-in item, `entry:<entry id>` for a line an earlier addendum added.\n  targetKey         String?\n  /// The new line, for ADDED and REPLACED.\n  name              String?\n  category          ItemCategory?\n  condition         ItemCondition?\n  quantity          Int            @default(1)\n  identifier        String?\n  notes             String?\n  /// The resolved repair this entry was started from.\n  maintenanceCaseId String?\n  /// The asset publishing created for this line, so a check-out copies the link.\n  propertyAssetId   String?\n  /// Upload intents survive a missing photo registration, so deleting the entry\n  /// can remove objects written by an outstanding signed upload URL.\n  uploadPaths       String[]       @default([])\n  createdAt         DateTime       @default(now())\n\n  addendum        ReportAddendum        @relation(fields: [addendumId], references: [id], onDelete: Cascade)\n  maintenanceCase MaintenanceCase?      @relation(fields: [maintenanceCaseId], references: [id], onDelete: SetNull)\n  propertyAsset   PropertyAsset?        @relation(fields: [propertyAssetId], references: [id], onDelete: SetNull)\n  photos          ReportAddendumPhoto[]\n\n  @@index([addendumId, createdAt])\n}\n\n/// A photo for an entry: uploaded under `addenda/<addendumId>/`, or the same object as a\n/// maintenance case's evidence, referenced rather than copied.\nmodel ReportAddendumPhoto {\n  id                    String   @id @default(cuid())\n  entryId               String\n  storagePath           String\n  mimeType              String\n  sizeBytes             Int?\n  note                  String?\n  /// \"Before\" or \"After\" for a repair's evidence.\n  label                 String?\n  /// Provenance only, so the same evidence is not attached twice.\n  maintenanceEvidenceId String?\n  /// Copied by value from the repair photo, so later marking there never changes it.\n  annotations           Json?\n  createdAt             DateTime @default(now())\n\n  entry ReportAddendumEntry @relation(fields: [entryId], references: [id], onDelete: Cascade)\n\n  @@index([entryId, createdAt])\n}\n\nenum AcknowledgementMethod {\n  OWN_ACCOUNT\n  IN_PERSON\n}\n\n/// A landlord or tenant saying \"I acknowledge this update\", against the exact content\n/// they were shown: signed in as themselves, or in person on the agent's phone.\nmodel AddendumAcknowledgement {\n  id             String                 @id @default(cuid())\n  addendumId     String\n  stakeholderId  String\n  acknowledgedAt DateTime               @default(now())\n  ipAddress      String?\n  contentHash    String\n  /// How it was given: on the party's own account, or in person on the agent's phone.\n  /// Null on acknowledgements from before the in-person path, which were all their own.\n  method         AcknowledgementMethod?\n\n  addendum    ReportAddendum @relation(fields: [addendumId], references: [id], onDelete: Cascade)\n  stakeholder Stakeholder    @relation(fields: [stakeholderId], references: [id])\n\n  @@unique([addendumId, stakeholderId])\n}\n\nenum DeletionRequestStatus {\n  REQUESTED\n  PROCESSING\n  COMPLETED\n}\n\n/// In-app requests are fulfilled by an operator under the approved retention policy.\nmodel AccountDeletionRequest {\n  id                      String                @id @default(cuid())\n  stakeholderId           String                @unique\n  status                  DeletionRequestStatus @default(REQUESTED)\n  requestedAt             DateTime              @default(now())\n  dueAt                   DateTime\n  completedAt             DateTime?\n  notificationSentAt      DateTime?\n  processingPolicyVersion String?\n  fulfilledUnderPolicy    String?\n  email                   String?\n\n  stakeholder   Stakeholder                   @relation(fields: [stakeholderId], references: [id])\n  storagePurges AccountDeletionStoragePurge[]\n\n  @@index([status, dueAt])\n  @@index([stakeholderId, requestedAt])\n}\n\n/// A durable prefix manifest for media belonging to an erased draft room. Signed\n/// upload URLs can remain valid for two hours after the room row is deleted; cleanup\n/// only completes after that window and a verified empty Storage listing.\nmodel AccountDeletionStoragePurge {\n  id          String    @id @default(cuid())\n  requestId   String\n  roomId      String    @unique\n  readyAt     DateTime\n  completedAt DateTime?\n\n  request AccountDeletionRequest @relation(fields: [requestId], references: [id], onDelete: Cascade)\n\n  @@index([requestId, completedAt])\n}\n\n/// Tombstone for a capture or room removed from the working report. The DB row may\n/// disappear before a still-valid signed upload URL expires, so Storage removal is\n/// delayed and retried independently of the request that deleted the row.\nmodel StoragePurge {\n  id          String    @id @default(cuid())\n  path        String    @unique\n  isPrefix    Boolean\n  readyAt     DateTime\n  completedAt DateTime?\n  createdAt   DateTime  @default(now())\n\n  @@index([completedAt, readyAt])\n}\n\nenum ErrorSource {\n  SERVER\n  WEB\n  ANDROID\n  IOS\n}\n\n/// One error, as it happened, from the server, an agent's browser, or the app. Grouped on read by\n/// `fingerprint`, a hash of where it came from and what it said with ids and numbers\n/// normalized out, so the same bug on two inspections is one problem rather than two.\n/// `notifiedAt` is stamped by the alert cron, which emails a fingerprint only the first\n/// time it is seen. Kept for 90 days, as the privacy policy says.\nmodel ErrorEvent {\n  /// A browser report carries its own UUID, so a retried batch cannot record twice.\n  id            String      @id @default(uuid())\n  source        ErrorSource\n  /// Where it was caught: render, action, route or api on the server; boundary, window\n  /// or rejection in the browser; flutter, platform or caught in the app.\n  context       String\n  name          String\n  message       String\n  stack         String?\n  /// React's digest for a server error. The browser shows it as the error's reference,\n  /// so it is how an agent's screenshot is matched to the stack.\n  digest        String?\n  path          String?\n  release       String?\n  userAgent     String?\n  fingerprint   String\n  stakeholderId String?\n  occurredAt    DateTime\n  createdAt     DateTime    @default(now())\n  notifiedAt    DateTime?\n\n  stakeholder Stakeholder? @relation(fields: [stakeholderId], references: [id], onDelete: Cascade)\n\n  @@index([fingerprint])\n  @@index([notifiedAt])\n  @@index([createdAt])\n  @@index([stakeholderId])\n}\n\nenum ProductEventSource {\n  WEB\n  ANDROID\n  IOS\n}\n\n/// Allowlisted usage events, with identity stamped by the authenticated server.\n/// No addresses, report tokens, free text or IPs. Kept for 90 days.\nmodel ProductEvent {\n  id            String             @id @default(uuid())\n  source        ProductEventSource\n  name          String\n  properties    Json\n  release       String?\n  stakeholderId String\n  occurredAt    DateTime\n  createdAt     DateTime           @default(now())\n\n  stakeholder Stakeholder @relation(fields: [stakeholderId], references: [id], onDelete: Cascade)\n\n  @@index([createdAt])\n  @@index([name, createdAt])\n  @@index([stakeholderId, createdAt])\n}\n\n/// Every report PDF Kivilo has handed out, by the SHA-256 of its exact bytes, so anyone\n/// holding a copy can check it is one we issued and has not been altered since\n/// (`src/lib/report-verification.ts`). Rows outlive the stored file, which is replaced\n/// whenever the report changes and deleted when its link is revoked: a genuine copy\n/// stays genuine.\nmodel IssuedReportFile {\n  sha256       String   @id\n  inspectionId String\n  storagePath  String\n  issuedAt     DateTime @default(now())\n\n  inspection Inspection @relation(fields: [inspectionId], references: [id], onDelete: Cascade)\n\n  @@index([inspectionId, issuedAt])\n  @@index([storagePath])\n}\n\n/// The landlord's or tenant's answer to the deposit statement in one published\n/// assessment version: agreed, or disputed with a reason. One per party per version and\n/// never edited; a revised assessment is a new version with its own answers, and the old\n/// ones stay against the old hash (`src/lib/statement-actions.ts`).\nmodel AssessmentResponse {\n  id                  String                @id @default(cuid())\n  assessmentVersionId String\n  stakeholderId       String\n  answer              StatementAnswer\n  /// Required to dispute.\n  reason              String?\n  method              AcknowledgementMethod\n  /// The version's `contentHash`, which covers the frozen deposit and every finding.\n  contentHash         String\n  ipAddress           String?\n  respondedAt         DateTime              @default(now())\n\n  assessmentVersion AssessmentVersion @relation(fields: [assessmentVersionId], references: [id], onDelete: Cascade)\n  stakeholder       Stakeholder       @relation(fields: [stakeholderId], references: [id])\n\n  @@unique([assessmentVersionId, stakeholderId])\n  @@index([stakeholderId])\n}\n\nenum StatementAnswer {\n  AGREED\n  DISPUTED\n}\n"
}

